import { createHash } from "node:crypto";

/** Bumped whenever the shape of anything `generate` writes changes (PER-100 §6). */
export const GENERATE_FORMAT_VERSION = 1;

// Every generated file carries one header line naming the format and a sha256 of
// the format version plus the file's other lines. A file whose hash no longer
// matches was hand-edited. The hash lives in the file, so the check needs no ledger.
const MARK = /@generated by loupe generate, do not edit \(formatVersion (\d+), sha256:([0-9a-f]{64})\)/;

const mark = (version: number, hash: string) =>
  `@generated by loupe generate, do not edit (formatVersion ${version}, sha256:${hash})`;

/** The exact header line: line 1 of a module, line 2 of a JSON object. */
const moduleLine = (text: string) => `// ${text}`;
const jsonLine = (text: string) => `  "$generated": "${text}",`;

const sha256 = (version: number, body: string) =>
  createHash("sha256").update(`${version}\n${body}`, "utf8").digest("hex");

/** Prepends the header comment to a TypeScript module body. */
export function stampModule(body: string): string {
  return `${moduleLine(mark(GENERATE_FORMAT_VERSION, sha256(GENERATE_FORMAT_VERSION, body)))}\n${body}`;
}

/**
 * Adds the header as a `"$generated"` key on the second line of a JSON body
 * from `stableJson`. `$` sorts before every letter, so the key stays first.
 */
export function stampJson(body: string): string {
  if (!body.startsWith("{\n") || body.startsWith("{\n}")) throw new Error("stampJson needs a non-empty JSON object");
  const line = jsonLine(mark(GENERATE_FORMAT_VERSION, sha256(GENERATE_FORMAT_VERSION, body)));
  return `{\n${line}\n${body.slice(2)}`;
}

export type HeaderState =
  /** No header line: the file was not written by `generate`. */
  | { kind: "foreign" }
  /** The header matches the rest of the file. */
  | { kind: "intact"; formatVersion: number }
  /** The header or the content changed since `generate` wrote it. */
  | { kind: "edited" };

export function readHeader(content: string): HeaderState {
  const lines = content.split("\n");
  const index = lines.findIndex((line) => MARK.test(line));
  if (index === -1) return { kind: "foreign" };
  const line = lines[index] ?? "";
  const [, digits, hash] = MARK.exec(line) ?? [];
  const version = Number(digits);
  const canonical = mark(version, hash ?? "");
  // The header must sit where generate puts it and say nothing else.
  const placed = (index === 0 && line === moduleLine(canonical)) || (index === 1 && line === jsonLine(canonical));
  const body = [...lines.slice(0, index), ...lines.slice(index + 1)].join("\n");
  return placed && sha256(version, body) === hash ? { kind: "intact", formatVersion: version } : { kind: "edited" };
}
